// Shape of the UI data generated by scripts/build-data.ts from data/*.json.
import type { Bait, Spot } from '../i18n/dictionaries.ts';

/** "HH:MM" or "MM-DD" window; `from > to` wraps over midnight / New Year. */
export type Window = { from: string; to: string };
/** `null` = unknown, `'always'` = any time / all year. */
export type Schedule = Window[] | 'always' | null;

export type UncertainField = 'time' | 'season' | 'bait';

export type Fish = {
  /** Stable progress key, never changes. */
  id: string;
  names: { cs: string; en: string };
  areas: string[];
  /** Exact spots inside an area, e.g. { "pinheira-beach": ["Pier"] }. */
  spots: Record<string, Spot[]>;
  time: Schedule;
  season: Schedule;
  rarity: 1 | 2 | 3 | 4 | 5;
  bait: Bait[];
  /** Catch length range in cm (fishaofunwiki), `null` = unknown. */
  size: { min: number; avg: number; max: number } | null;
  /** World record label ("449 cm", "(448–449 cm)?"), `null` = unknown. Already carries its own "?". */
  record: string | null;
  /** Fields the UI marks with "?" (the record is excluded, its label has the "?"). */
  uncertain: UncertainField[];
  /** Every fish has a glowing variant (user decision, not from the source). */
  glowing: true;
  /** Natural size of public/fish/<id>.webp, for layout without shifts. */
  img: { w: number; h: number };
};

export type AreaKind = 'area' | 'tournament' | 'backyard';

export type Area = {
  id: string;
  name: string;
  kind: AreaKind;
  spots: Spot[];
  count: number;
};

// ---- furniture (home decorations) ----------------------------------------

export type FurnitureType = 'wall' | 'floor' | 'furniture' | 'plant' | 'painting';
/** Most common first. `normal` (3 items) has no defined place in the source; it sits next to common. */
export const FURNITURE_RARITIES = ['very-common', 'common', 'normal', 'uncommon', 'rare', 'very-rare', 'epic', 'legendary'] as const;
export type FurnitureRarity = typeof FURNITURE_RARITIES[number];

/** How to get it: shop from a level, the Furniture Factory, a mission, free in the inventory, or closed-beta gift. */
export type Availability =
  | { kind: 'level'; level: number }
  | { kind: 'factory' } | { kind: 'mission' } | { kind: 'free' } | { kind: 'beta' };

/** Months 1–12, `from > to` wraps over New Year. */
export type MonthRange = { from: number; to: number };

export type FurnitureItem = {
  /** Stable progress key, never changes. */
  id: string;
  names: { cs: string; en: string };
  /** Set id, or 'plants' / 'paintings' / 'other' for items outside sets. */
  collection: string;
  type: FurnitureType | null;
  /** `null` = unknown. */
  rarity: FurnitureRarity | null;
  availability: Availability | null;
  /** In the shop only in these months; `null` = unknown. */
  season: MonthRange | 'always' | null;
  img: { w: number; h: number };
};

export type FurnitureCollection = {
  id: string;
  /** set = a named furniture set; type = items outside sets grouped by type; other = the rest. */
  kind: 'set' | 'type' | 'other';
  names: { cs: string; en: string };
  /** public/furniture/sets/<id>.webp exists. */
  badge: boolean;
  count: number;
};
